#!/usr/bin/env python3
import csv, html, json, pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
rows=list(csv.DictReader(open(ROOT/"lists"/"calibration-top30.csv",encoding="utf-8-sig")))
summary=json.load(open(ROOT/"results"/"calibration-summary.json"))
summary_by_repo={x["repo"]:x for x in summary["repositories_detail"]}
data=[]
for row in rows:
 slug=row["repo"].replace("/","__")
 card=json.load(open(ROOT/"results"/"cards"/(slug+".json")))
 facts=json.load(open(ROOT/"results"/"facts"/(slug+".json")))
 detail=summary_by_repo[row["repo"]]
 units=[json.loads(x) for x in open(ROOT/"results"/"units"/(slug+".jsonl")) if x.strip()]
 data.append({"rank":int(row["rank"]),"stars":int(row["stars"]),"description":row["description"],"meta":{"url":row["url"],"created_at":row["created_at"],"pushed_at":row["pushed_at"],"commits":int(row["commits"]),"language":row["language"],"license":row["license"] or "—","disk_kb":int(row["disk_kb"]),"copies":int(row["copies"]),"facts_extracted_at":facts["extracted_at"],"card_generated_at":card["generated_at"],"worker":card["worker"],"model":"gpt-6-luna","effort":"high","analysis_elapsed_seconds":detail["analysis_elapsed_seconds"],"validation":"passed","coverage_read_all":card["coverage"]["read_all"],"coverage_skipped":len(card["coverage"].get("skipped",[]))},"card":card,"units":units})
payload=json.dumps(data,ensure_ascii=False).replace("</","<\\/")
page=r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>DSH Plugin Calibration Review</title>
<style>
:root{--bg:#0b0d10;--panel:#12161b;--panel2:#171c22;--line:#28313b;--text:#eef3f8;--muted:#8f9baa;--green:#45d483;--amber:#f5bd4f;--blue:#60a5fa;--red:#f47174;--violet:#a78bfa}
*{box-sizing:border-box}html,body{margin:0;height:100%;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
button,input,select,textarea{font:inherit}.app{display:grid;grid-template-rows:auto 1fr;height:100%}
header{display:flex;align-items:center;gap:18px;padding:16px 22px;border-bottom:1px solid var(--line);background:rgba(11,13,16,.92)}
.brand{font-weight:750;letter-spacing:-.02em}.brand small{display:block;color:var(--muted);font-size:11px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;margin-top:2px}
.stats{margin-left:auto;display:flex;gap:8px}.stat{padding:7px 11px;border:1px solid var(--line);border-radius:8px;color:var(--muted);font-size:12px}.stat b{color:var(--text);font-size:14px;margin-right:4px}
main{display:grid;grid-template-columns:380px 1fr;min-height:0}.sidebar{border-right:1px solid var(--line);display:flex;flex-direction:column;min-width:0}
.filters{padding:14px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:1fr 110px;gap:8px}
input,select,textarea{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:9px 10px;outline:none}
input:focus,select:focus,textarea:focus{border-color:var(--blue)}.list{overflow:auto;padding:8px}
.repo{padding:12px;border:1px solid transparent;border-radius:10px;cursor:pointer;margin-bottom:4px}.repo:hover{background:var(--panel)}.repo.active{background:var(--panel2);border-color:#3a4653}
.repo-top{display:flex;align-items:center;gap:8px}.rank{color:var(--muted);font-size:11px;width:24px}.repo-name{font-size:13px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.badges{display:flex;gap:5px;margin:7px 0 0 32px;flex-wrap:wrap}.badge{font-size:10px;padding:3px 6px;border-radius:5px;background:#222a33;color:#b9c4d0}.grade-S{color:#6ee7b7}.grade-A{color:#93c5fd}.reviewed{color:var(--green)}
.content{overflow:auto;padding:24px 30px}.empty{height:100%;display:grid;place-items:center;color:var(--muted)}
.hero{display:flex;align-items:flex-start;gap:18px;border-bottom:1px solid var(--line);padding-bottom:20px}.hero-main{flex:1}.eyebrow{color:var(--muted);font-size:12px}.hero h1{font-size:26px;margin:5px 0 8px;letter-spacing:-.03em}.one{color:#cbd5df;line-height:1.6;margin:0;max-width:900px}.actions{display:flex;gap:8px;flex-wrap:wrap}
.btn{border:1px solid var(--line);background:var(--panel2);color:var(--text);border-radius:8px;padding:9px 12px;cursor:pointer}.btn:hover{border-color:#4b5c6d}.btn.approve{border-color:#246b45;color:#85efb1}.btn.reject{border-color:#74383a;color:#fca5a5}
.tabs{display:flex;gap:4px;padding:16px 0 12px;position:sticky;top:-24px;background:var(--bg);z-index:2}.tab{border:0;background:transparent;color:var(--muted);padding:8px 11px;border-radius:7px;cursor:pointer}.tab.active{background:var(--panel2);color:var(--text)}
.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px}.card h3{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:0 0 10px}.card p{margin:0;line-height:1.65;color:#d7dee6}
.kv{display:grid;grid-template-columns:120px 1fr;gap:7px 12px;font-size:13px}.kv dt{color:var(--muted)}.kv dd{margin:0}.unit{padding:14px 0;border-bottom:1px solid var(--line)}.unit-head{display:flex;align-items:center;gap:8px;margin-bottom:7px}.unit-type{font-size:10px;text-transform:uppercase;color:var(--blue);font-weight:700;letter-spacing:.08em}.unit-lang{font-size:10px;color:var(--muted)}.unit p{margin:0;line-height:1.65;color:#d6dde5}.evidence{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.ev{font-family:ui-monospace,monospace;font-size:10px;color:#9fc5ef;background:#172332;border:1px solid #273e56;padding:3px 6px;border-radius:4px}
.section-title{font-size:16px;margin:8px 0 12px}.quality{display:grid;grid-template-columns:90px 44px 1fr;gap:8px;font-size:12px;padding:8px 0;border-bottom:1px solid var(--line)}.quality .score{color:var(--green);font-weight:700}
.reviewbox{max-width:760px}.reviewbox textarea{width:100%;min-height:150px;resize:vertical;margin:10px 0}.hint{font-size:12px;color:var(--muted);line-height:1.55}
@media(max-width:900px){main{grid-template-columns:1fr}.sidebar{max-height:42vh;border-right:0;border-bottom:1px solid var(--line)}.content{padding:18px}.grid{grid-template-columns:1fr}.stats{display:none}}
</style></head>
<body><div class="app"><header><div class="brand">DSH Plugin Review<small>Calibration · fixed commits · 30 repositories</small></div><div class="stats" id="stats"></div></header>
<main><aside class="sidebar"><div class="filters"><input id="q" placeholder="搜索仓库、能力、问法…"><select id="topic"><option value="">全部主题</option></select><select id="grade"><option value="">全部质量</option><option>S</option><option>A</option><option>B</option><option>C</option><option>D</option></select><select id="state"><option value="">全部状态</option><option value="approved">已通过</option><option value="changes">需修改</option><option value="pending">待审核</option></select></div><div class="list" id="list"></div></aside>
<section class="content" id="content"><div class="empty">从左侧选择一个插件开始审核</div></section></main></div>
<script>
const DATA=__DATA__;
const KEY="dsh-review-v1";let reviews=JSON.parse(localStorage.getItem(KEY)||"{}");let selected=null,tab="overview";
const $=s=>document.querySelector(s), esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const display=d=>d.card.name||d.card.repo.split("/")[1]; const status=repo=>reviews[repo]?.status||"pending";
function save(){localStorage.setItem(KEY,JSON.stringify(reviews));renderStats();renderList()}
function renderStats(){let a=0,c=0;DATA.forEach(d=>{if(status(d.card.repo)==="approved")a++;if(status(d.card.repo)==="changes")c++});$("#stats").innerHTML='<span class="stat"><b>'+a+'</b>通过</span><span class="stat"><b>'+c+'</b>需修改</span><span class="stat"><b>'+(30-a-c)+'</b>待审核</span>'}
function initFilters(){[...new Set(DATA.map(d=>d.card.topics.primary))].sort().forEach(x=>$("#topic").insertAdjacentHTML("beforeend",'<option>'+esc(x)+'</option>'));["q","topic","grade","state"].forEach(id=>$("#"+id).addEventListener(id==="q"?"input":"change",renderList))}
function filtered(){let q=$("#q").value.toLowerCase(),tp=$("#topic").value,g=$("#grade").value,st=$("#state").value;return DATA.filter(d=>{let blob=(d.card.repo+" "+JSON.stringify(d.card)+" "+d.units.map(x=>x.text).join(" ")).toLowerCase();return(!q||blob.includes(q))&&(!tp||d.card.topics.primary===tp)&&(!g||d.card.quality.grade===g)&&(!st||status(d.card.repo)===st)})}
function renderList(){let arr=filtered();$("#list").innerHTML=arr.map(d=>{let st=status(d.card.repo);return '<div class="repo '+(selected===d.card.repo?"active":"")+'" data-repo="'+esc(d.card.repo)+'"><div class="repo-top"><span class="rank">#'+d.rank+'</span><span class="repo-name">'+esc(d.card.repo)+'</span></div><div class="badges"><span class="badge">'+esc(d.card.topics.primary)+'</span><span class="badge grade-'+d.card.quality.grade+'">'+d.card.quality.grade+'</span><span class="badge '+(st==="approved"?"reviewed":"")+'">'+({pending:"待审核",approved:"已通过",changes:"需修改"}[st])+'</span></div></div>'}).join("");document.querySelectorAll(".repo").forEach(x=>x.onclick=()=>{selected=x.dataset.repo;tab="overview";renderList();renderDetail()})}
function evidence(xs){return xs?.length?'<div class="evidence">'+xs.map(x=>'<span class="ev">'+esc(x)+'</span>').join("")+'</div>':""}
function overview(d){let c=d.card,q=c.quality,req=c.requirements,m=d.meta;return '<div class="grid"><div class="card"><h3>能力摘要</h3><p>'+esc(c.one_liner.zh)+'</p></div><div class="card"><h3>分类与接入面</h3><dl class="kv"><dt>主题</dt><dd>'+esc(c.topics.primary)+(c.topics.secondary.length?" · "+c.topics.secondary.map(esc).join(" · "):"")+'</dd><dt>客户端</dt><dd>'+c.clients.map(esc).join(" · ")+'</dd><dt>Surface</dt><dd>'+c.surfaces.map(esc).join(" · ")+'</dd><dt>安装</dt><dd>'+esc(c.install.method)+'</dd></dl></div><div class="card"><h3>仓库快照 metadata</h3><dl class="kv"><dt>Repository</dt><dd><a target="_blank" style="color:var(--blue)" href="'+esc(m.url)+'">'+esc(c.repo)+'</a></dd><dt>Stars</dt><dd>'+d.stars.toLocaleString()+'</dd><dt>Language</dt><dd>'+esc(m.language)+'</dd><dt>License</dt><dd>'+esc(m.license)+'</dd><dt>创建时间</dt><dd>'+esc(m.created_at)+'</dd><dt>最后推送</dt><dd>'+esc(m.pushed_at)+'</dd><dt>Commits</dt><dd>'+m.commits.toLocaleString()+'</dd><dt>Copies</dt><dd>'+m.copies+'</dd><dt>仓库大小</dt><dd>'+m.disk_kb.toLocaleString()+' KB</dd><dt>固定 commit</dt><dd><span class="ev">'+esc(c.commit)+'</span></dd></dl></div><div class="card"><h3>处理 metadata</h3><dl class="kv"><dt>Facts 抽取</dt><dd>'+esc(m.facts_extracted_at)+'</dd><dt>卡片生成</dt><dd>'+esc(m.card_generated_at)+'</dd><dt>模型</dt><dd>'+esc(m.model)+' / '+esc(m.effort)+'</dd><dt>Worker</dt><dd>'+esc(m.worker)+'</dd><dt>分析耗时</dt><dd>'+m.analysis_elapsed_seconds.toFixed(1)+' 秒</dd><dt>校验</dt><dd><span class="reviewed">'+esc(m.validation)+'</span></dd><dt>源码覆盖</dt><dd>'+(m.coverage_read_all?'完整':'部分')+' · skipped '+m.coverage_skipped+'</dd></dl></div><div class="card"><h3>配置与外部服务</h3><dl class="kv"><dt>API keys</dt><dd>'+(req.api_keys.map(x=>esc(x.name)).join(", ")||"无")+'</dd><dt>账号</dt><dd>'+(req.accounts.map(esc).join(", ")||"无")+'</dd><dt>服务</dt><dd>'+(req.external_services.map(x=>esc(x.host)).join(", ")||"无")+'</dd><dt>本地要求</dt><dd>'+(req.local.map(esc).join("；")||"无")+'</dd></dl></div><div class="card"><h3>实现质量 · '+q.grade+'</h3>'+["completeness","code","docs","maintenance","tests"].map(k=>'<div class="quality"><b>'+k+'</b><span class="score">'+q[k].score+'/5</span><span>'+esc(q[k].reason)+'</span></div>').join("")+'</div></div>'}
function units(d){let types=["card","intent","feature","caveat","declared","readme"],html="";types.forEach(t=>{let xs=d.units.filter(x=>x.type===t);if(!xs.length)return;html+='<h2 class="section-title">'+t+' · '+xs.length+'</h2>'+xs.map(x=>'<article class="unit"><div class="unit-head"><span class="unit-type">'+t+'</span><span class="unit-lang">'+esc(x.lang)+'</span></div><p>'+esc(x.text)+'</p>'+evidence(x.evidence)+'</article>').join("")});return html}
function sources(d){let c=d.card, all=[];function walk(v){if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==="object")Object.entries(v).forEach(([k,x])=>{if(k==="evidence"&&Array.isArray(x))all.push(...x);else walk(x)})}walk(c);d.units.forEach(u=>all.push(...(u.evidence||[])));all=[...new Set(all)].sort();return '<h2 class="section-title">Evidence · '+all.length+'</h2><p class="hint">路径相对于固定 commit 的仓库根目录。审核时可在源码 checkout 中按路径和行号核对。</p><div class="evidence">'+all.map(x=>'<span class="ev">'+esc(x)+'</span>').join("")+'</div>'}
function review(d){let r=reviews[d.card.repo]||{};return '<div class="reviewbox"><h2 class="section-title">审核结论</h2><p class="hint">状态和备注只保存在当前浏览器的 localStorage，不会修改分析结果。</p><textarea id="notes" placeholder="准确性、遗漏功能、检索问法、质量评分问题…">'+esc(r.notes||"")+'</textarea><div class="actions"><button class="btn approve" data-set="approved">通过</button><button class="btn reject" data-set="changes">需要修改</button><button class="btn" data-set="pending">重置为待审核</button></div></div>'}
function renderDetail(){let d=DATA.find(x=>x.card.repo===selected);if(!d)return;let c=d.card;$("#content").innerHTML='<div class="hero"><div class="hero-main"><div class="eyebrow">#'+d.rank+' · '+d.stars.toLocaleString()+' stars · '+esc(c.commit.slice(0,10))+'</div><h1>'+esc(display(d))+'</h1><p class="one">'+esc(c.one_liner.zh)+'</p></div><div class="actions"><a class="btn" target="_blank" href="https://github.com/'+esc(c.repo)+'/tree/'+esc(c.commit)+'">查看源码</a></div></div><div class="tabs">'+[["overview","概览"],["units","索引文本"],["sources","Evidence"],["review","审核"]].map(([x,l])=>'<button class="tab '+(tab===x?"active":"")+'" data-tab="'+x+'">'+l+'</button>').join("")+'</div><div id="pane">'+({overview:overview(d),units:units(d),sources:sources(d),review:review(d)}[tab])+'</div>';document.querySelectorAll(".tab").forEach(x=>x.onclick=()=>{tab=x.dataset.tab;renderDetail()});document.querySelectorAll("[data-set]").forEach(x=>x.onclick=()=>{let notes=$("#notes").value;reviews[c.repo]={status:x.dataset.set,notes,updatedAt:new Date().toISOString()};save();renderDetail()});let n=$("#notes");if(n)n.oninput=()=>{let r=reviews[c.repo]||{status:"pending"};r.notes=n.value;reviews[c.repo]=r;localStorage.setItem(KEY,JSON.stringify(reviews))}}
initFilters();renderStats();renderList();if(DATA.length){selected=DATA[0].card.repo;renderList();renderDetail()}
</script></body></html>'''.replace("__DATA__",payload)
out=ROOT/"review-site";out.mkdir(exist_ok=True);(out/"index.html").write_text(page)
print(json.dumps({"repos":len(data),"bytes":len(page.encode()),"path":str(out/"index.html")}))
